import React, { useState } from "react";
import { motion } from "framer-motion";
import { BRAND } from "./Content";
import { ArrowDownRight, Sparkles, Crown, Gem, Truck } from "lucide-react";

// Gold Particle Component with animation
const GoldParticle = ({ delay, duration, size, x, y }) => (
  <motion.div
    className="absolute rounded-full pointer-events-none"
    style={{
      width: size,
      height: size,
      left: `${x}%`,
      top: `${y}%`,
      background: "radial-gradient(circle, #d4af37 0%, transparent 70%)",
      opacity: 0.6,
    }}
    animate={{
      y: [0, -30, -15, -40, 0],
      x: [0, 10, -15, 5, 0],
      opacity: [0.3, 0.7, 0.5, 0.8, 0.3],
    }}
    transition={{
      duration: duration,
      delay: delay,
      repeat: Infinity,
      ease: "easeInOut",
    }}
  />
);

// Generate random particles
const particles = Array.from({ length: 30 }, (_, i) => ({
  id: i,
  delay: Math.random() * 5,
  duration: 4 + Math.random() * 4,
  size: 4 + Math.random() * 8,
  x: Math.random() * 100,
  y: Math.random() * 100,
}));

// Button hover animation
const buttonHover = {
  rest: { scale: 1, y: 0 },
  hover: { scale: 1.05, y: -2 },
  tap: { scale: 0.98 }
};

// Feature pill animation
const pillVariants = {
  initial: { opacity: 0, y: 20, scale: 0.9 },
  animate: (i) => ({
    opacity: 1,
    y: 0,
    scale: 1,
    transition: { delay: 1.2 + i * 0.1, duration: 0.4 }
  })
};

// Stats animation
const statVariants = {
  initial: { opacity: 0, scale: 0.8 },
  animate: (i) => ({
    opacity: 1,
    scale: 1,
    transition: { delay: 1.4 + i * 0.1, duration: 0.5 }
  })
};

export default function Hero({ onOpenQuote }) {
  const [videoLoaded, setVideoLoaded] = useState(false);

  const fallbackImage = "url('https://images.unsplash.com/photo-1519167758481-83f550bb49b3?auto=compress&cs=tinysrgb&w=1920&h=1080&fit=crop')";

  return (
    <section id="hero-section" className="relative w-full" style={{ background: "#ffffff" }}>

      {/* TOP SECTION - Video Background */}
      <div className="relative w-full overflow-hidden" style={{ height: "75vh", minHeight: 500 }}>

        {/* Video Background */}
        <motion.video
          autoPlay
          muted
          loop
          playsInline
          className="absolute inset-0 w-full h-full object-cover"
          poster="https://images.pexels.com/photos/36547498/pexels-photo-36547498.jpeg?auto=compress&cs=tinysrgb&w=1920"
          onLoadedData={() => setVideoLoaded(true)}
          initial={{ opacity: 0 }}
          animate={{ opacity: videoLoaded ? 1 : 0 }}
          transition={{ duration: 1, ease: "ease" }}
        >
          <source src="https://cdn.coverr.co/videos/coverr-wedding-decorations-5764/1080p.mp4" type="video/mp4" />
        </motion.video>

        {/* Fallback Background Image */}
        <motion.div
          className="absolute inset-0"
          style={{
            backgroundImage: fallbackImage,
            backgroundSize: "cover",
            backgroundPosition: "center",
          }}
          initial={{ opacity: 1 }}
          animate={{ opacity: videoLoaded ? 0 : 1 }}
          transition={{ duration: 1, ease: "ease" }}
        />

        {/* Dark Overlay */}
        <div className="absolute inset-0" style={{ background: "linear-gradient(180deg, rgba(26,8,10,0.55) 0%, rgba(26,8,10,0.4) 50%, rgba(26,8,10,0.6) 100%)" }} />

        {/* Gold Particles with Framer Motion */}
        <div className="absolute inset-0 overflow-hidden pointer-events-none">
          {particles.map((p) => (
            <GoldParticle key={p.id} {...p} />
          ))}
        </div>

        {/* Animated Gold Border */}
        <motion.div
          className="absolute top-0 left-0 w-full h-1"
          style={{ background: "linear-gradient(90deg, transparent 0%, #d4af37 50%, transparent 100%)" }}
          animate={{
            opacity: [0.7, 1, 0.7],
            scaleX: [0.95, 1, 0.95],
          }}
          transition={{ duration: 3, repeat: Infinity, ease: "easeInOut" }}
        />

        {/* Hero Content */}
        <div className="absolute inset-0 flex flex-col justify-center px-8 md:px-16 lg:px-24">
          <div className="max-w-5xl">

            {/* Location Badge */}
            <motion.div
              initial={{ opacity: 0, x: -30 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ duration: 0.8, delay: 0.2 }}
              className="flex items-center gap-3 mb-6"
            >
              <motion.div
                className="w-16 h-px"
                style={{ background: "linear-gradient(90deg, transparent, #d4af37)" }}
                initial={{ width: 0 }}
                animate={{ width: 64 }}
                transition={{ duration: 0.8, delay: 0.4 }}
              />
              <motion.span
                className="text-xs tracking-[0.35em] uppercase font-semibold"
                style={{ color: "#d4af37" }}
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ delay: 0.5 }}
              >
                Ludhiana, Punjab | Pan India Delivery
              </motion.span>
            </motion.div>

            {/* Main Title */}
            <motion.h1
              initial={{ opacity: 0, y: 30 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.8, delay: 0.4 }}
              className="serif leading-none tracking-tight mb-4"
              style={{ fontSize: "clamp(48px, 10vw, 120px)", fontWeight: 400, color: "#ffffff", textShadow: "0 4px 40px rgba(0,0,0,0.4)" }}
            >
              D SAJAWAT
            </motion.h1>

            {/* Tagline */}
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.8, delay: 0.6 }}
              className="flex items-center gap-3 mb-4"
            >
              <motion.div
                animate={{ rotate: [0, 10, -10, 0] }}
                transition={{ duration: 2, repeat: Infinity, repeatDelay: 1 }}
              >
                <Crown size={24} color="#d4af37" />
              </motion.div>
              <p className="serif text-lg md:text-3xl" style={{ color: "#f7e7ce", fontStyle: "italic", fontWeight: 400 }}>
                {BRAND.tagline}
              </p>
            </motion.div>

            {/* Subtitle */}
            <motion.p
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.8, delay: 0.8 }}
              className="text-sm md:text-base max-w-xl"
              style={{ color: "rgba(255,255,255,0.85)", lineHeight: 1.7 }}
            >
              Premium fabrics for weddings & events. Trusted by India's top decorators with Pan India delivery.
            </motion.p>
          </div>
        </div>


        {/* Bottom Gradient */}
        <div className="absolute bottom-0 left-0 w-full h-32" style={{ background: "linear-gradient(to bottom, transparent, #ffffff)" }} />
      </div>

      {/* BOTTOM CONTENT SECTION */}
      <div className="relative w-full px-8 md:px-16 lg:px-24 py-12 md:py-16" style={{ background: "#ffffff" }}>

        {/* CTA Buttons */}
        <motion.div
          className="flex flex-wrap justify-center gap-4 mb-8"
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8, delay: 1 }}
        >
          <motion.a
            href="#collections"
            className="btn-gold text-base md:text-lg px-8 py-3 flex items-center gap-2"
            variants={buttonHover}
            initial="rest"
            whileHover="hover"
            whileTap="tap"
          >
            <Sparkles size={18} strokeWidth={1.6} />
            Explore Our Collection
          </motion.a>

          <motion.button
            onClick={onOpenQuote}
            className="btn-ghost text-base md:text-lg px-8 py-3 flex items-center gap-2"
            type="button"
            variants={buttonHover}
            initial="rest"
            whileHover="hover"
            whileTap="tap"
          >
            Get a Quote
            <ArrowDownRight size={18} strokeWidth={1.6} />
          </motion.button>
        </motion.div>

        {/* Features Pills */}
        <motion.div
          className="flex flex-wrap justify-center gap-3 mb-8"
          initial="initial"
          animate="animate"
        >
          {[
            { icon: Gem, text: "Premium Quality" },
            { icon: Truck, text: "Pan India Delivery" },
            { icon: Crown, text: "Bulk Orders" },
          ].map(({ icon: Icon, text }, i) => (
            <motion.div
              key={text}
              className="flex items-center gap-2 px-4 py-2 rounded-full cursor-pointer"
              style={{ background: "#fff9ed", border: "1px solid rgba(212,175,55,0.3)" }}
              custom={i}
              variants={pillVariants}
              whileHover={{
                scale: 1.05,
                backgroundColor: "#faf8f5",
                borderColor: "rgba(212,175,55,0.6)",
                transition: { duration: 0.2 }
              }}
            >
              <motion.div
                animate={{ rotate: [0, 360] }}
                transition={{ duration: 20, repeat: Infinity, ease: "linear" }}
              >
                <Icon size={16} color="#d4af37" />
              </motion.div>
              <span className="text-sm font-medium" style={{ color: "#1a080a" }}>{text}</span>
            </motion.div>
          ))}
        </motion.div>

        {/* Stats Grid */}
        <motion.div
          className="grid grid-cols-2 md:grid-cols-4 gap-4 max-w-4xl mx-auto"
          initial="initial"
          animate="animate"
        >
          {[
            { num: "12+", label: "Years of Craft" },
            { num: "350+", label: "Decorators" },
            { num: "1800+", label: "Events Adorned" },
            { num: "240+", label: "Cities Reached" },
          ].map(({ num, label }, i) => (
            <motion.div
              key={label}
              className="text-center p-4 rounded-lg cursor-pointer"
              style={{ background: "linear-gradient(135deg, #fffdf5, #fff9ed)", border: "1px solid rgba(212,175,55,0.2)" }}
              custom={i}
              variants={statVariants}
              whileHover={{
                scale: 1.05,
                boxShadow: "0 8px 30px rgba(212,175,55,0.3)",
                transition: { duration: 0.2 }
              }}
            >
              <motion.div
                className="text-3xl font-bold"
                style={{ color: "#d4af37" }}
                animate={{ scale: [1, 1.05, 1] }}
                transition={{ duration: 2, repeat: Infinity, delay: i * 0.2 }}
              >
                {num}
              </motion.div>
              <div className="text-xs uppercase tracking-wider mt-1" style={{ color: "rgba(26,8,10,0.5)" }}>{label}</div>
            </motion.div>
          ))}
        </motion.div>
      </div>
    </section>
  );
}
